    "summaryJa": "【鈴木善幸内閣（増税なき財政再建・土光臨調）】「和の政治」「増税なき財政再建」を掲げ第二次臨時行政調査会（土光臨調）を発足させた。",
    "summaryEn": "[Suzuki Zenko Cabinet] Promoted 'Politics of Harmony' and fiscal reform without tax hikes via the Doko Commission.",
